import{_t as e,it as t,n,rt as r}from"./chunks/framework.DaD4z1Q-.js";var i=JSON.parse(`{"title":"Command line reference","description":"All Strauss-RS commands and options: prefix, diff, explain, init, migrate, include-autoloader, plan, config, packages, files, symbols and analyse.","frontmatter":{"title":"Command line reference","description":"All Strauss-RS commands and options: prefix, diff, explain, init, migrate, include-autoloader, plan, config, packages, files, symbols and analyse."},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}`),a={name:`reference/cli.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="command-line" tabindex="-1">Command line <a class="header-anchor" href="#command-line" aria-label="Permalink to “Command line”">​</a></h1><p>Run the commands through the installer script, which passes everything after its name to the program:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/strauss-rs.sh</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">comman</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [options]</span></span></code></pre></div><p>If you have installed the binary yourself, use <code>strauss-rs &lt;command&gt;</code> instead. Run <code>strauss-rs &lt;command&gt; --help</code> for the same information in your terminal.</p><h2 id="options-for-every-command" tabindex="-1">Options for every command <a class="header-anchor" href="#options-for-every-command" aria-label="Permalink to “Options for every command”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>-q</code>, <code>--quiet</code></td><td>Show no progress and no summary, only warnings and errors.</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td>Print help.</td></tr><tr><td><code>-V</code>, <code>--version</code></td><td>Print the version (on the main command only).</td></tr></tbody></table><p>Most commands also take:</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>-C</code>, <code>--project-dir &lt;DIR&gt;</code></td><td>The plugin or theme root, which holds <code>strauss.json</code> and <code>composer.json</code>. Defaults to the current folder.</td></tr></tbody></table><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><a href="#prefix"><code>prefix</code></a></td><td>Copy packages to the target directory, rename symbols, write the autoloader.</td></tr><tr><td><a href="#diff"><code>diff</code></a></td><td>Show the changes <code>prefix</code> would make.</td></tr><tr><td><a href="#explain"><code>explain</code></a></td><td>Explain what happens to one symbol, and why.</td></tr><tr><td><a href="#init"><code>init</code></a></td><td>Write a starting <code>strauss.json</code>.</td></tr><tr><td><a href="#migrate"><code>migrate</code></a></td><td>Move <code>extra.strauss</code> from <code>composer.json</code> into <code>strauss.json</code>.</td></tr><tr><td><a href="#include-autoloader"><code>include-autoloader</code></a></td><td>Make <code>vendor/autoload.php</code> load the prefixed packages.</td></tr><tr><td><a href="#plan"><code>plan</code></a></td><td>Show which symbols would be renamed, and why others would not.</td></tr><tr><td><a href="#config"><code>config</code></a></td><td>Print the resolved configuration as JSON.</td></tr><tr><td><a href="#packages"><code>packages</code></a></td><td>List the packages to process.</td></tr><tr><td><a href="#files"><code>files</code></a></td><td>List the files of those packages.</td></tr><tr><td><a href="#symbols"><code>symbols</code></a></td><td>List the symbols each package declares.</td></tr><tr><td><a href="#analyse"><code>analyse</code></a></td><td>Analyse one PHP file.</td></tr></tbody></table><h3 id="prefix" tabindex="-1">prefix <a class="header-anchor" href="#prefix" aria-label="Permalink to “prefix”">​</a></h3><p>Copies the packages to <code>target_directory</code> with their namespaces and global symbols renamed, and writes the autoloader. <code>vendor</code> is left as it is unless <code>delete_vendor_files</code> or <code>delete_vendor_packages</code> is set. A summary and any warnings go to stderr.</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>--dry-run</code></td><td>Work out what would be written, and write nothing.</td></tr><tr><td><code>--json</code></td><td>Print what was written as JSON, instead of the summary.</td></tr><tr><td><code>--parallel[=&lt;auto|false|N&gt;]</code></td><td>How many workers read the files. Overrides <code>parallel</code>. <code>auto</code> (or <code>true</code>) is one per CPU, <code>false</code> or <code>1</code> is one worker, a number caps the workers.</td></tr><tr><td><code>--updateCallSites[=&lt;true|false|PATHS&gt;]</code></td><td>Which of your files to update where they use prefixed names. Overrides <code>update_call_sites</code>. <code>true</code> is the files in your <code>autoload</code>, <code>false</code> is none, or give a comma-separated list of files and folders.</td></tr></tbody></table><h3 id="diff" tabindex="-1">diff <a class="header-anchor" href="#diff" aria-label="Permalink to “diff”">​</a></h3><p>Shows the changes <code>prefix</code> would make, as a diff. Nothing is written. It runs the same analysis as <code>plan</code>, then works out every place that has to change so that the renamed symbols still work.</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>--package &lt;NAME&gt;</code></td><td>Only show the files of this package. Can be given more than once.</td></tr><tr><td><code>--json</code></td><td>Show the edits as JSON, with their positions, instead of a diff.</td></tr><tr><td><code>--parallel[=&lt;auto|false|N&gt;]</code></td><td>As for <code>prefix</code>.</td></tr><tr><td><code>--updateCallSites[=&lt;true|false|PATHS&gt;]</code></td><td>As for <code>prefix</code>.</td></tr></tbody></table><h3 id="explain" tabindex="-1">explain <a class="header-anchor" href="#explain" aria-label="Permalink to “explain”">​</a></h3><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/strauss-rs.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> explain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;GuzzleHttp\\Client&#39;</span></span></code></pre></div><p>Shows whether a class, function, constant or namespace is renamed, what to, and which setting decided it. Symbols that PHP or a preset provides are explained too, even when no package declares them. It exits with an error if nothing matches, and lists similar names.</p><p>The name is the full name of the symbol, such as <code>GuzzleHttp\\Client</code>, <code>my_function</code> or <code>ABSPATH</code>. A leading backslash is ignored. Names are matched without regard to case, except constants.</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>--kind &lt;KIND&gt;</code></td><td>Only consider one kind of symbol, for a name that is more than one thing. One of <code>namespace</code>, <code>class</code>, <code>interface</code>, <code>trait</code>, <code>enum</code>, <code>function</code>, <code>constant</code>.</td></tr><tr><td><code>--json</code></td><td>Print the explanation as JSON.</td></tr><tr><td><code>--parallel[=&lt;auto|false|N&gt;]</code></td><td>As for <code>prefix</code>.</td></tr></tbody></table><h3 id="init" tabindex="-1">init <a class="header-anchor" href="#init" aria-label="Permalink to “init”">​</a></h3><p>Writes a starting <code>strauss.json</code>, with the prefixes worked out from <code>composer.json</code>. Dependencies go under <code>&lt;your namespace&gt;\\Vendor</code> so they cannot meet your own classes. It refuses to replace an existing <code>strauss.json</code> unless you pass <code>--force</code>.</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>--force</code></td><td>Replace <code>strauss.json</code> if there is one.</td></tr><tr><td><code>--dry-run</code></td><td>Show what would be written, and write nothing.</td></tr><tr><td><code>--namespace-prefix &lt;PREFIX&gt;</code></td><td>The <code>namespace_prefix</code> to write, instead of the one worked out.</td></tr><tr><td><code>--classmap-prefix &lt;PREFIX&gt;</code></td><td>The <code>classmap_prefix</code> to write, instead of the one worked out.</td></tr><tr><td><code>--target-directory &lt;DIR&gt;</code></td><td>The <code>target_directory</code> to write, if not <code>vendor-prefixed</code>.</td></tr><tr><td><code>--composer-scripts</code></td><td>Add scripts to <code>composer.json</code> that run <code>prefix</code> after <code>composer install</code> and <code>composer update</code>, without asking.</td></tr><tr><td><code>--no-composer-scripts</code></td><td>Do not add the Composer scripts, and do not ask.</td></tr></tbody></table><p>Your <code>composer.json</code> keeps its key order and indentation when scripts are added.</p><h3 id="migrate" tabindex="-1">migrate <a class="header-anchor" href="#migrate" aria-label="Permalink to “migrate”">​</a></h3><p>Moves Strauss PHP&#39;s <code>extra.strauss</code> from <code>composer.json</code> into <code>strauss.json</code>. It checks the options are ones Strauss-RS knows before writing anything, then removes <code>extra.strauss</code>. It sets <code>classmap_prefix</code> where Strauss PHP would have worked it out differently, so your class names stay the same. See <a href="/strauss-rs/guide/migrating.html">moving from Strauss PHP</a>.</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>--force</code></td><td>Replace <code>strauss.json</code> if there is one.</td></tr><tr><td><code>--dry-run</code></td><td>Show what would be written, and write nothing.</td></tr></tbody></table><h3 id="include-autoloader" tabindex="-1">include-autoloader <a class="header-anchor" href="#include-autoloader" aria-label="Permalink to “include-autoloader”">​</a></h3><p>Adds a <code>require_once</code> of the target directory&#39;s <code>autoload.php</code> to <code>vendor/autoload.php</code>, before Composer&#39;s loader is returned. It is safe to run again. Run <code>prefix</code> first so there is an autoloader to include. This is what the <code>include_autoloader</code> setting does after <code>prefix</code>.</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>--dry-run</code></td><td>Work out what would change, and write nothing.</td></tr></tbody></table><h3 id="plan" tabindex="-1">plan <a class="header-anchor" href="#plan" aria-label="Permalink to “plan”">​</a></h3><p>Shows which symbols would be renamed, to what, and why not the others, as JSON. Without <code>--package</code> this is every symbol, which for a large project is a lot. The <code>summary</code> part has the counts.</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>--package &lt;NAME&gt;</code></td><td>Only show the symbols this package declares. Can be given more than once.</td></tr><tr><td><code>--parallel[=&lt;auto|false|N&gt;]</code></td><td>As for <code>prefix</code>.</td></tr></tbody></table><h3 id="config" tabindex="-1">config <a class="header-anchor" href="#config" aria-label="Permalink to “config”">​</a></h3><p>Prints the resolved configuration as JSON, with every setting shown with its default or inferred value, in the form <code>strauss.json</code> takes. It applies any options given here first.</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>--updateCallSites[=&lt;true|false|PATHS&gt;]</code></td><td>As for <code>prefix</code>.</td></tr><tr><td><code>--parallel[=&lt;auto|false|N&gt;]</code></td><td>As for <code>prefix</code>.</td></tr></tbody></table><h3 id="packages" tabindex="-1">packages <a class="header-anchor" href="#packages" aria-label="Permalink to “packages”">​</a></h3><p>Lists the packages to process as JSON: those in <code>packages</code>, and everything they require. It reads <code>vendor/composer/installed.json</code>, so run <code>composer install</code> first. Warnings go to stderr.</p><h3 id="files" tabindex="-1">files <a class="header-anchor" href="#files" aria-label="Permalink to “files”">​</a></h3><p>Lists the files of those packages as JSON, and which would be copied. Every file in a package is listed, except those git would leave out of an archive: <code>.git</code>, files matched by <code>.gitignore</code>, and <code>export-ignore</code> files.</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>--parallel[=&lt;auto|false|N&gt;]</code></td><td>As for <code>prefix</code>.</td></tr></tbody></table><h3 id="symbols" tabindex="-1">symbols <a class="header-anchor" href="#symbols" aria-label="Permalink to “symbols”">​</a></h3><p>Lists the symbols each package declares as JSON: namespaces, classes, interfaces, traits, enums, functions and constants. It reads every <code>.php</code> file of every package, so it can take a moment. PHP&#39;s own symbols, which polyfills redeclare, are listed separately as <code>built_ins</code>. Files that cannot be read are reported on stderr.</p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>--parallel[=&lt;auto|false|N&gt;]</code></td><td>As for <code>prefix</code>.</td></tr></tbody></table><h3 id="analyse" tabindex="-1">analyse <a class="header-anchor" href="#analyse" aria-label="Permalink to “analyse”">​</a></h3><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/strauss-rs.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analyse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path/to/file.php</span></span></code></pre></div><p>Reads one PHP file and prints the symbols it declares and refers to. Useful when you want to see how Strauss-RS reads a file. This command takes the file as its only argument, plus <code>-q</code>.</p>`,48)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};